import asyncio
import httpx


async def generate(ctx, api):
    """RunningHub OpenAPI v2 视频生成源 (AI App 2095868555916038145)。

    参数提示: nodeId 27=时长(秒), 28=prompt, 29=aspect_ratio/megapixels, 6=首帧图。

    工作方式(重要):
      本 Studio 对代码源不做工具层轮询, 故本携程在一次调用内完成
      「提交 -> 有界轮询 /query -> 取回 video_url」全链路(封顶 MAX_WAIT_S)。
      另支持: 若调用方携带 task_id 且无 prompt, 则仅做单次查询即返回。

    沙箱约束: 仅可 import asyncio / httpx。
    """
    APP_ID = "2095868555916038145"
    BASE = "https://www.runninghub.cn/openapi/v2"
    RUN_URL = f"{BASE}/run/ai-app/{APP_ID}"
    QUERY_URL = f"{BASE}/query"

    # ============================================================
    # API KEY 注入位（已填入用户提供的 Key；如需更换只改这一行）
    # ============================================================
    HARDCODED_API_KEY = "6704ef3723904f51b6cee0f73ea2304a"

    POLL_INTERVAL_S = 6      # 轮询间隔
    MAX_WAIT_S = 840         # 单次调用内最长等待 14 分钟(低于 code_timeout 1200)

    NODE_PROMPT = "28"
    NODE_DURATION = "27"
    NODE_FRAME = "29"
    NODE_IMAGE = "6"

    AR_FIELDDATA = ('["COMBO", {"default": "9:16 (Portrait Widescreen)", '
                    '"options": ["1:1 (Square)", "2:3 (Portrait Photo)", "3:2 (Photo)", '
                    '"3:4 (Portrait Standard)", "4:3 (Standard)", "9:16 (Portrait Widescreen)", '
                    '"16:9 (Widescreen)", "21:9 (Ultrawide)"], '
                    '"tooltip": "The aspect ratio for the output dimensions.", '
                    '"multiselect": false}]')

    AR_OPTIONS = {
        "1:1": "1:1 (Square)", "2:3": "2:3 (Portrait Photo)", "3:2": "3:2 (Photo)",
        "3:4": "3:4 (Portrait Standard)", "4:3": "4:3 (Standard)",
        "9:16": "9:16 (Portrait Widescreen)", "16:9": "16:9 (Widescreen)",
        "21:9": "21:9 (Ultrawide)",
    }

    DONE = ("SUCCESS", "SUCCEEDED", "COMPLETED", "FINISHED")
    BAD = ("FAILED", "ERROR", "CANCELED", "CANCELLED")

    # ---------------- 工具函数 ----------------
    def _key():
        cands = [HARDCODED_API_KEY]
        for name in ("api_key", "RUNNINGHUB_API_KEY", "runninghub_api_key",
                     "runninghub_key", "token", "access_token", "api_token"):
            try:
                cands.append(ctx.get(name))
            except Exception:
                pass
        try:
            cands.append(api.get("get_api_key", lambda: "")())
        except Exception:
            pass
        try:
            env = ctx.get("env") or {}
            if isinstance(env, dict):
                for name in ("RUNNINGHUB_API_KEY", "RUNNINGHUB_KEY", "RUNNINGHUB_TOKEN"):
                    cands.append(env.get(name))
        except Exception:
            pass
        for c in cands:
            if c and str(c).strip():
                return str(c).strip()
        return ""

    def _box(obj):
        if isinstance(obj, dict):
            d = obj.get("data")
            if isinstance(d, dict):
                return d
        return obj if isinstance(obj, dict) else {}

    def _extract_url(results):
        for it in (results or []):
            if not isinstance(it, dict):
                continue
            u = it.get("url") or it.get("fileUrl") or it.get("outputUrl") or ""
            if u:
                return u
        return ""

    def _norm_ar(raw):
        r = (raw or "").strip()
        if not r:
            return AR_OPTIONS["9:16"]
        if "(" in r:
            return r
        r = r.replace("：", ":").split()[0]
        return AR_OPTIONS.get(r, AR_OPTIONS["9:16"])

    def _success(tid, url, results, raw):
        return {"status": "SUCCESS", "task_id": tid, "taskId": tid,
                "video_url": url, "url": url, "output_url": url,
                "results": results, "raw": raw}

    async def _poll_once(client, headers, tid):
        """单次查询, 返回 (status_upper, url, raw_dict)。秒回, 不阻塞。"""
        r = await client.post(QUERY_URL, headers=headers, json={"taskId": tid})
        if r.status_code != 200:
            raise RuntimeError(f"RunningHub 查询失败 HTTP {r.status_code}: {r.text[:300]}")
        try:
            data = r.json() or {}
        except Exception:
            raise RuntimeError(f"RunningHub 查询响应非 JSON: {r.text[:300]}")
        b = _box(data)
        st = str(b.get("status") or data.get("status") or "").upper()
        res = b.get("results") or data.get("results") or []
        return st, _extract_url(res), res, data

    # ---------------- 入参解析 ----------------
    dyn = ctx.get("dynamic_inputs") or {}
    raw_prompt = (ctx.get("prompt") or "").strip()
    task_id = (ctx.get("task_id") or dyn.get("task_id") or "").strip()
    prompt = raw_prompt
    if raw_prompt.upper().startswith("QUERY:"):
        task_id = raw_prompt.split(":", 1)[1].strip()
        prompt = ""

    key = _key()
    if not key:
        raise RuntimeError("RunningHub 鉴权缺失: HARDCODED_API_KEY 为空且源配置 api_key 也未填。")
    headers = {"Content-Type": "application/json", "Authorization": "Bearer " + key}
    for probe in ("headers", "custom_headers"):
        try:
            extra = ctx.get(probe)
            if isinstance(extra, dict):
                for k, v in extra.items():
                    if k and v and k not in headers:
                        headers[k] = v
        except Exception:
            pass

    # ============================================================
    # 纯查询模式: 有 task_id 且无 prompt -> 单次秒回
    # ============================================================
    if task_id and not prompt:
        async with httpx.AsyncClient(timeout=30) as client:
            st, url, res, data = await _poll_once(client, headers, task_id)
        if st in DONE and url:
            return _success(task_id, url, res, data)
        if st in BAD:
            raise RuntimeError(f"RunningHub 任务失败({st}): {str(data)[:300]}")
        return {"status": "PENDING", "task_id": task_id, "taskId": task_id,
                "video_url": None, "results": None, "raw": data}

    # ============================================================
    # 提交模式
    # ============================================================
    if not prompt:
        raise ValueError("RunningHub 源需要 prompt（或 QUERY:<taskId> 查询）")

    try:
        duration = max(1, min(30, int(float(ctx.get("duration")
                                            or dyn.get("duration") or 5))))
    except Exception:
        duration = 5

    ar_val = _norm_ar(ctx.get("aspect_ratio") or dyn.get("aspect_ratio") or "9:16")
    first_frame = (ctx.get("first_frame") or ctx.get("first_frame_url")
                   or dyn.get("first_frame") or "").strip()

    node_info = [
        {"nodeId": NODE_PROMPT, "fieldName": "prompt",
         "fieldValue": prompt, "description": "prompt"},
        {"nodeId": NODE_DURATION, "fieldName": "value",
         "fieldValue": str(duration), "description": "value"},
        {"nodeId": NODE_FRAME, "fieldName": "aspect_ratio",
         "fieldData": AR_FIELDDATA, "fieldValue": ar_val, "description": "aspect_ratio"},
        {"nodeId": NODE_FRAME, "fieldName": "megapixels",
         "fieldValue": "0.7000000000000001", "description": "megapixels"},
    ]
    if first_frame:
        node_info.append({"nodeId": NODE_IMAGE, "fieldName": "image",
                          "fieldValue": first_frame, "description": "image"})

    payload = {
        "nodeInfoList": node_info,
        "instanceType": (ctx.get("instance_type") or dyn.get("instance_type") or "default"),
        "usePersonalQueue": str(ctx.get("use_personal_queue") or "false").lower(),
    }

    async with httpx.AsyncClient(timeout=60) as client:
        r = await client.post(RUN_URL, headers=headers, json=payload)
        try:
            body_raw = r.json() or {}
        except Exception:
            body_raw = {}

        body = _box(body_raw)
        if r.status_code in (401, 403) or body_raw.get("code") == 1602:
            raise RuntimeError(
                f"RunningHub 鉴权被拒 (HTTP {r.status_code} / code={body_raw.get('code')} / "
                f"msg={body_raw.get('msg')})。")
        if r.status_code != 200:
            raise RuntimeError(f"RunningHub 提交失败 HTTP {r.status_code}: {r.text[:300]}")

        new_task = str(body.get("taskId") or body_raw.get("taskId") or "").strip()
        if not new_task:
            raise RuntimeError(f"RunningHub 未返回 taskId: {str(body_raw)[:300]}")

        # 提交即出结果(同步场景)
        url_now = _extract_url(body.get("results"))
        if url_now:
            return _success(new_task, url_now, body.get("results"), body_raw)

        # ================= 有界轮询至终态 =================
        waited = 0
        last = {}
        while waited < MAX_WAIT_S:
            await asyncio.sleep(POLL_INTERVAL_S)
            waited += POLL_INTERVAL_S
            st, url, res, data = await _poll_once(client, headers, new_task)
            last = data
            if st in DONE:
                if not url:
                    raise RuntimeError(f"任务成功但无结果URL: {str(data)[:300]}")
                return _success(new_task, url, res, data)
            if st in BAD:
                raise RuntimeError(
                    f"RunningHub 任务失败({st}): "
                    f"{_box(data).get('errorCode', '')} "
                    f"{_box(data).get('errorMessage', '')} {str(data)[:200]}")

    # 超时: 回传 task_id 供后续 QUERY:<taskId> 续查
    return {"status": "PENDING", "task_id": new_task, "taskId": new_task,
            "video_url": None, "results": None, "raw": last,
            "note": f"等待 {MAX_WAIT_S}s 未完成, 可用 prompt='QUERY:{new_task}' 续查"}

