        v = ctx.get(k) or dyn.get(k)
        if isinstance(v, str) and v.startswith(("http://", "https://", "data:")):
            ordered.append(v)
            break
    seen, uniq = set(), []
    for u in ordered:
        if u not in seen:
            seen.add(u)
            uniq.append(u)

