            raise RuntimeError(f"AutoDL 未返回 task_id: {str(resp)[:400]}")
        return {"video_url": None, "task_id": new_id, "status": "SUBMITTED"}

import asyncio
import httpx

async def generate(ctx, api):
    AUTODL_BASE = "https://autodl.art/api/v1"
    WORKFLOW_ID = "minimax_h3_image_audio_to_video_v2_15s"
    AUTODL_API_KEY = "3jfV2WXEzzGkSW1gcuZwAtTAMbDhruqwgphMu9mXQ5EIKapd"

    headers = {
        "Authorization": f"Bearer {AUTODL_API_KEY}",
        "Content-Type": "application/json"
    }

    dyn = ctx.get("dynamic_inputs") or {}
    prompt = (ctx.get("prompt") or "").strip()
    task_id = (ctx.get("task_id") or dyn.get("task_id") or "").strip()

    # 查询模式：有 task_id 且无 prompt → 单次 GET（秒回，绝不阻塞）。
    # 由框架后台轮询（_poll_code_video_task）或调用方携带 task_id 复用，勿在此 sleep 循环。
    if task_id and not prompt:
        async with httpx.AsyncClient(timeout=15) as client:
            r = await client.get(f"{AUTODL_BASE}/comfyui/comfyui_workflow/result/{task_id}", headers=headers)
            r.raise_for_status()
            data = (r.json() or {}).get("data", {}) or {}
            status = str(data.get("status") or "").upper()
            results = data.get("results") or []
            url = None
            for item in results:
                if isinstance(item, dict) and item.get("type") == "video" and item.get("url"):
                    url = item["url"]
                    break
            if not url and results:
                first = results[0]
                url = first.get("url") if isinstance(first, dict) else (first if isinstance(first, str) else None)
            if url:
                return {"video_url": url, "status": data.get("status"), "task_id": task_id}
            if status in ("FAILED", "ERROR", "FAIL", "CANCELLED"):
                raise RuntimeError(f"AutoDL 任务失败 task_id={task_id}: {str(data)[:300]}")
            return {"video_url": None, "status": data.get("status") or "QUEUED", "task_id": task_id}

    if not prompt:
        raise ValueError("缺少 prompt")

    # 组装 body（严格对齐官方能跑通的示例；时长钳位 1-15 防参数非法）
    try:
        duration = int(ctx.get("duration") or 5)
    except (ValueError, TypeError):
        duration = 5
    duration = max(1, min(15, duration))
    body = {
        "prompt": prompt,
        "duration": duration,
        "resolution": ctx.get("resolution") or "768p竖",
    }
    seed = ctx.get("seed")
    if seed is not None:
        try:
            s = int(seed)
            if s > 0:
                body["seed"] = s
        except (ValueError, TypeError):
            pass

    # 首帧/参考图/尾帧 → ref_image_0..8（保序去重；仅公网 http(s)，本地 /storage 路径 AutoDL 不认则跳过）
    ordered_images = []
    for key in ("first_frame", "first_frame_url"):
        v = ctx.get(key) or dyn.get(key)
        if isinstance(v, str) and v.startswith(("http://", "https://", "data:")):
            ordered_images.append(v)
            break
    for url in (ctx.get("reference_images") or dyn.get("reference_images") or []):
        if isinstance(url, str) and url.startswith(("http://", "https://", "data:")):
            ordered_images.append(url)
    for key in ("last_frame", "last_frame_url"):
        v = ctx.get(key) or dyn.get(key)
        if isinstance(v, str) and v.startswith(("http://", "https://", "data:")):
            ordered_images.append(v)
            break
    seen = set()
    uniq_images = []
    for u in ordered_images:
        if u not in seen:
            seen.add(u)
            uniq_images.append(u)
    for i, url in enumerate(uniq_images[:9]):
        body[f"ref_image_{i}"] = url

    # 参考音频 → ref_audio_0..2（兼容 reference_audios / ref_audio / 单字符串三种形态）
    audios = []
    for key in ("reference_audios", "ref_audio", "reference_audio"):
        v = ctx.get(key) if ctx.get(key) is not None else dyn.get(key)
        if isinstance(v, str) and v:
            audios.append(v)
        elif isinstance(v, list):
            audios.extend(v)
    n = 0
    seen_a = set()
    for url in audios:
        if isinstance(url, str) and url.startswith(("http://", "https://", "data:")) and url not in seen_a:
            seen_a.add(url)
            body[f"ref_audio_{n}"] = url
            n += 1
        if n >= 3:
            break

    # 提交即返 task_id（绝不在此轮询等终态：外层 Agent 40s 即超时；框架后台轮询接管）
    async with httpx.AsyncClient(timeout=20) as client:
        r = await client.post(f"{AUTODL_BASE}/comfyui/comfyui_workflow/{WORKFLOW_ID}", json=body, headers=headers)
        r.raise_for_status()
        resp = r.json() or {}
        if resp.get("code") not in (None, "Success", "success"):
            raise RuntimeError(f"AutoDL 提交失败: {str(resp)[:400]}")
        new_task_id = (resp.get("data") or {}).get("task_id")
        if not new_task_id:
            raise RuntimeError(f"AutoDL 未返回 task_id: {str(resp)[:400]}")
        return {"video_url": None, "task_id": new_task_id, "status": "SUBMITTED"}

import httpx
import base64

API_BASE = "https://www.runninghub.cn/openapi/v2"
RUN_URL = API_BASE + "/run/ai-app/2097935043799896065"
QUERY_URL = API_BASE + "/query"
UPLOAD_URL = API_BASE + "/media/upload/binary"
ASPECT_OPTIONS = [
    "1:1 (Square)", "2:3 (Portrait Photo)", "3:2 (Photo)", "3:4 (Portrait Standard)",
    "4:3 (Standard)", "9:16 (Portrait Widescreen)", "16:9 (Widescreen)", "21:9 (Ultrawide)",
]


async def _upload_ref(client, api_key, value, idx):
    """参考图值 → RunningHub 文件名：data: URI/公网URL 先传后填；已是文件名则原样返回。"""
    v = str(value or "").strip()
    if not v or v == "None":
        return None
    if not (v.startswith("data:") or v.startswith("http://") or v.startswith("https://")):
        return v
    if v.startswith("data:"):
        try:
            raw = base64.b64decode(v.split(",", 1)[1])
        except Exception as e:
            raise RuntimeError(f"参考图{idx} base64 解码失败: {e}")
    else:
        gr = await client.get(v, timeout=120)
        gr.raise_for_status()
        raw = gr.content
    if not raw:
        raise RuntimeError(f"参考图{idx}内容为空")
    # 上传只能用 Bearer 头：带上 Content-Type: application/json 会破坏 multipart 边界
    up = await client.post(
        UPLOAD_URL, headers={"Authorization": f"Bearer {api_key}"},
        files={"file": (f"image{idx}.png", raw, "image/png")}, timeout=300,
    )
    up.raise_for_status()
    uj = up.json()
    if uj.get("code") != 0:
        raise RuntimeError(f"参考图{idx}上传失败: {uj.get('message') or str(uj)[:300]}")
    data = uj.get("data") or {}
    dl = data.get("download_url") or data.get("fileName")
    if not dl:
        raise RuntimeError(f"参考图{idx}上传未返回文件名: {str(uj)[:300]}")
    return dl


