import httpx
import base64

API_BASE = "https://www.runninghub.ai/openapi/v2"
RUN_URL = API_BASE + "/run/ai-app/2086022574387339266"
QUERY_URL = API_BASE + "/query"
UPLOAD_URL = API_BASE + "/media/upload/binary"
ASPECT_OPTIONS = [
    "1:1 (Square)", "2:3 (Portrait Photo)", "3:2 (Photo)", "3:4 (Portrait Standard)",
    "4:3 (Standard)", "9:16 (Portrait Widescreen)", "16:9 (Widescreen)", "21:9 (Ultrawide)",
]
_EXT_BY_MIME = {"jpeg": "jpg", "mpeg": "mp3", "x-m4a": "m4a", "quicktime": "mov", "x-wav": "wav"}
_MIME_BY_EXT = {
    "png": "image/png", "jpg": "image/jpeg", "jpeg": "image/jpeg", "webp": "image/webp",
    "mp3": "audio/mpeg", "wav": "audio/wav", "m4a": "audio/mp4",
    "mp4": "video/mp4", "webm": "video/webm", "mov": "video/quicktime",
}
_KNOWN_EXTS = ("png", "jpg", "jpeg", "webp", "mp3", "wav", "m4a", "mp4", "webm", "mov")


def _is_remote(v):
    return v.startswith("data:") or v.startswith("http://") or v.startswith("https://")


def _ext_of(v, default_ext):
    if v.startswith("data:"):
        mime = v[5:].split(";", 1)[0].split("/")[-1].lower()
        return _EXT_BY_MIME.get(mime, mime or default_ext)
    path = v.split("?", 1)[0].lower()
    for e in _KNOWN_EXTS:
        if path.endswith("." + e):
            return e
    return default_ext


async def _upload(client, api_key, value, idx, kind, default_ext):
    """媒体值 → RunningHub 文件名：data: URI / 公网URL 先上传后回填；已是文件名则原样透传。"""
    v = str(value or "").strip()
    if not v or v == "None":
        return None
    if not _is_remote(v):
        return v
    if v.startswith("data:"):
        try:
            raw = base64.b64decode(v.split(",", 1)[1])
        except Exception as e:
            raise RuntimeError(f"{kind}{idx} base64 解码失败: {e}")
    else:
        gr = await client.get(v, timeout=120)
        gr.raise_for_status()
        raw = gr.content
    if not raw:
        raise RuntimeError(f"{kind}{idx}内容为空")
    ext = _ext_of(v, default_ext)
    mime = _MIME_BY_EXT.get(ext, "application/octet-stream")
    # 上传只能带 Bearer 头：附带 Content-Type: application/json 会破坏 multipart 边界
    up = await client.post(
        UPLOAD_URL, headers={"Authorization": f"Bearer {api_key}"},
        files={"file": (f"{kind}{idx}.{ext}", raw, mime)}, timeout=300,
    )
    up.raise_for_status()
    uj = up.json()
    if uj.get("code") != 0:
        raise RuntimeError(f"{kind}{idx}上传失败: {uj.get('message') or str(uj)[:300]}")
    d = uj.get("data") or {}
    dl = d.get("download_url") or d.get("fileName")
    if not dl:
        raise RuntimeError(f"{kind}{idx}上传未返回文件名: {str(uj)[:300]}")
    return dl


async def generate(ctx, api):
    dyn = ctx.get("dynamic_inputs") or {}
    api_key = ctx.get("api_key")
    if not api_key and isinstance(api, dict) and callable(api.get("get_api_key")):
        api_key = api["get_api_key"]()
    api_key = str(api_key or "").strip()
    if not api_key:
        raise RuntimeError("缺少 RunningHub API Key（请在生成源里配置 Key 后重试）")

    headers = {"Authorization": f"Bearer {api_key}", "Content-Type": "application/json"}
    task_id = str(ctx.get("task_id") or dyn.get("task_id") or "").strip()
    prompt = str(ctx.get("prompt") or "").strip()

    async with httpx.AsyncClient(timeout=600) as client:
        # ── 查询分支：有 task_id 且无 prompt，单次查询秒回，绝不 sleep ──
        if task_id and not prompt:
            q = await client.post(QUERY_URL, headers=headers, json={"taskId": task_id})
            q.raise_for_status()
            qj = q.json() or {}
            status = str(qj.get("status") or "").upper()
            if status in ("CREATE", "QUEUED", "RUNNING", "PENDING"):
                return {"video_url": None, "task_id": task_id, "status": status}
            if status == "SUCCESS":
                results = qj.get("results") or []
                for item in results:  # 多保存节点会混出图片，视频优先挑 mp4/webm/mov
                    if isinstance(item, dict):
                        url = str(item.get("url") or "")
                        ot = str(item.get("outputType") or "").lower()
                        if url and (ot in ("mp4", "webm", "mov") or ot == "" or "mp4" in url.lower()):
                            return {"video_url": url}
                for item in results:
                    if isinstance(item, dict) and item.get("url"):
                        return {"video_url": item["url"]}
                    if isinstance(item, str) and item:
                        return {"video_url": item}
                raise RuntimeError(f"任务成功但无结果URL: {str(qj)[:300]}")
            if status == "CANCEL":  # CANCEL 需映射成框架终态词 CANCELLED
                status = "CANCELLED"
            raise RuntimeError(f"任务失败({status or 'UNKNOWN'}): {qj.get('errorMessage') or str(qj)[:300]}")

        # ── 提交分支：上传媒体 → 组装 nodeInfoList → 立即返回 task_id ──
        if not prompt:
            raise ValueError("缺少 prompt")

        first = ctx.get("first_frame_url") or ctx.get("first_frame") or dyn.get("first_frame")
        refs = ctx.get("reference_images") or dyn.get("reference_images") or []
        if isinstance(refs, str):
            refs = [refs]
        refs = [str(r) for r in refs if r][:3]
        auds = ctx.get("reference_audios") or dyn.get("reference_audios") or []
        if isinstance(auds, str):
            auds = [auds]
        auds = [str(a) for a in auds if a][:2]
        ref_video = ctx.get("reference_video_url") or ctx.get("reference_video") or dyn.get("reference_video")

        aspect = str(ctx.get("aspect_ratio") or dyn.get("aspect_ratio") or "9:16 (Portrait Widescreen)")
        if aspect not in ASPECT_OPTIONS:
            aspect = "9:16 (Portrait Widescreen)"
        instance_type = str(ctx.get("instance_type") or dyn.get("instance_type") or "default")
        if instance_type not in ("default", "plus", "ultra"):
            instance_type = "default"

        img1 = await _upload(client, api_key, first, 1, "image", "png") if first else None
        img2 = await _upload(client, api_key, refs[0], 2, "image", "png") if len(refs) > 0 else None
        img3 = await _upload(client, api_key, refs[1], 3, "image", "png") if len(refs) > 1 else None
        img_shared = await _upload(client, api_key, refs[2], 4, "image", "png") if len(refs) > 2 else None
        aud1 = await _upload(client, api_key, auds[0], 1, "audio", "mp3") if len(auds) > 0 else None
        aud2 = await _upload(client, api_key, auds[1], 2, "audio", "mp3") if len(auds) > 1 else None
        vid = await _upload(client, api_key, ref_video, 1, "video", "mp4") if ref_video else None

        node_info_list = [
            {"nodeId": "150", "fieldName": "value", "fieldValue": prompt, "description": "结构化提示词"},
            {"nodeId": "115", "fieldName": "aspect_ratio", "fieldValue": aspect, "description": "画幅"},
            {"nodeId": "144", "fieldName": "audio", "fieldValue": aud1 or "None", "description": "drive_audio 音色参考"},
            {"nodeId": "160", "fieldName": "audio", "fieldValue": aud2 or "None", "description": "ref_audio_0 音色参考"},
        ]
        for nid, val, desc in (("141", img1, "Picture1 主体参考"), ("142", img2, "参考图1"), ("143", img3, "参考图2")):
            if val:  # 未提供时不下发，保留应用内保存的默认值
                node_info_list.append({"nodeId": nid, "fieldName": "image", "fieldValue": val, "description": desc})
        if img_shared:  # 示例中 161/165/166 为同一张共享参考图
            for nid in ("161", "165", "166"):
                node_info_list.append({"nodeId": nid, "fieldName": "image", "fieldValue": img_shared, "description": "共享参考图"})
        if vid:
            node_info_list.append({"nodeId": "164", "fieldName": "video", "fieldValue": vid, "description": "参考视频"})

        payload = {"nodeInfoList": node_info_list, "instanceType": instance_type, "usePersonalQueue": "false"}
        r = await client.post(RUN_URL, headers=headers, json=payload)
        r.raise_for_status()
        rj = r.json() or {}
        new_id = str(rj.get("taskId") or ((rj.get("data") or {}).get("taskId") if isinstance(rj.get("data"), dict) else "") or "").strip()
        if not new_id:
            raise RuntimeError(f"提交未返回 taskId: {str(rj)[:300]}")
        return {"video_url": None, "task_id": new_id, "status": "SUBMITTED"}

